#include "ringbuf.h"
#include <stdlib.h>
#include <string.h>

struct ringbuf {
    uint8_t *buf;
    size_t capacity;
    size_t head;  /* next write position */
    size_t data_len;  /* bytes currently stored */
};

ringbuf_t *rb_create(size_t capacity)
{
    ringbuf_t *rb = NULL;

    if (capacity == 0)
        return NULL;

    rb = malloc(sizeof(*rb));
    if (!rb)
        return NULL;

    rb->buf = calloc(capacity, sizeof(uint8_t));
    if (!rb->buf) {
        free(rb);
        return NULL;
    }

    rb->capacity = capacity;
    rb->head = 0;
    rb->data_len = 0;
    return rb;
}

void rb_destroy(ringbuf_t *rb)
{
    if (!rb)
        return;
    free(rb->buf);
    free(rb);
}

static inline size_t write_idx(const ringbuf_t *rb, size_t offset)
{
    return (rb->head + offset) % rb->capacity;
}

size_t rb_write(ringbuf_t *rb, const uint8_t *data, size_t len)
{
    size_t space;
    size_t n;

    if (!rb || !data || len == 0)
        return 0;

    space = rb->capacity - rb->data_len;
    if (space == 0)
        return 0;

    n = len < space ? len : space;

    /* Determine the boundary where wrapping would occur */
    const size_t to_end = rb->capacity - rb->head;

    if (rb->head + n <= rb->capacity) {
        memcpy(rb->buf + rb->head, data, n);
    } else {
        /* First chunk: from head to end of buffer */
        memcpy(rb->buf + rb->head, data, to_end > n ? n : to_end);
        if (to_end < n)
            memcpy(rb->buf, data + to_end, n - to_end);
    }

    rb->head = (rb->head + n) % rb->capacity;

    /* When buffer was empty we keep head at 0 so the invariant
       data_len == 0 <-> head == 0 is maintained cleanly. */
    if (rb->data_len == 0 && n > 0) {
        rb->head = n % rb->capacity;
        /* no actual pointer needed, just advance logically */
    } else {
        rb->head = rb->head;  /* already updated above via modulo */
    }

    /* Simpler approach: track head as the next write position directly */
    /* Actually let me use a cleaner design (see revised version below) */

    rb->data_len += n;

    return n;
}

size_t rb_read(ringbuf_t *rb, uint8_t *out, size_t len)
{
    if (!rb || !out || len == 0 || rb->data_len == 0)
        return 0;

    const size_t to_end = rb->capacity - (rb->head - rb->data_len);

    /* ... */

    return 0;
}

#include "ringbuf.h"
#include <stdlib.h>
#include <string.h>

struct ringbuf {
    uint8_t *buf;
    size_t capacity;
    size_t head;       /* index of the oldest byte (read pointer) */
    size_t tail;       /* index of the next write position      */
    size_t data_len;   /* bytes currently stored                  */
};

ringbuf_t *rb_create(size_t capacity)
{
    ringbuf_t *rb;

    if (capacity == 0)
        return NULL;

    rb = malloc(sizeof(*rb));
    if (!rb)
        return NULL;

    rb->buf = calloc(capacity, sizeof(uint8_t));
    if (!rb->buf) {
        free(rb);
        return NULL;
    }

    rb->capacity = capacity;
    rb->head = 0;
    rb->tail = 0;
    rb->data_len = 0;
    return rb;
}

void rb_destroy(ringbuf_t *rb)
{
    if (!rb)
        return;
    free(rb->buf);
    free(rb);
}

size_t rb_write(ringbuf_t *rb, const uint8_t *data, size_t len)
{
    size_t n, to_end, remain;

    if (!rb || !data || len == 0)
        return 0;

    if (rb->data_len == rb->capacity)
        return 0;              /* full */

    n = len < (rb->capacity - rb->data_len) ? len : (rb->capacity - rb->data_len);

    to_end = rb->capacity - rb->tail;   /* space until end of buffer */
    if (n <= to_end) {
        memcpy(rb->buf + rb->tail, data, n);
    } else {
        remain = n - to_end;
        memcpy(rb->buf + rb->tail, data, to_end);
        memcpy(rb->buf, data + to_end, remain);
    }

    rb->tail = (rb->tail + n) % rb->capacity;
    rb->data_len += n;
    return n;
}

size_t rb_read(ringbuf_t *rb, uint8_t *out, size_t len)
{
    size_t n, to_end;

    if (!rb || !out || len == 0 || rb->data_len == 0)
        return 0;

    n = len < rb->data_len ? len : rb->data_len;

    to_end = rb->capacity - rb->head;   /* space until end of buffer */
    if (n <= to_end) {
        memcpy(out, rb->buf + rb->head, n);
    } else {
        memcpy(out, rb->buf + rb->head, to_end);
        memcpy(out + to_end, rb->buf, n - to_end);
    }

    rb->head = (rb->head + n) % rb->capacity;
    rb->data_len -= n;
    return n;
}

size_t rb_peek(const ringbuf_t *rb, uint8_t *out, size_t len)
{
    size_t n, to_end;

    if (!rb || !out || len == 0 || rb->data_len == 0)
        return 0;

    n = len < rb->data_len ? len : rb->data_len;

    to_end = rb->capacity - rb->head;
    if (n <= to_end) {
        memcpy(out, rb->buf + rb->head, n);
    } else {
        memcpy(out, rb->buf + rb->head, to_end);
        memcpy(out + to_end, rb->buf, n - to_end);
    }

    return n;
}

size_t rb_size(const ringbuf_t *rb)
{
    if (!rb)
        return 0;
    return rb->data_len;
}

size_t rb_capacity(const ringbuf_t *rb)
{
    if (!rb)
        return 0;
    return rb->capacity;
}

void rb_clear(ringbuf_t *rb)
{
    if (!rb)
        return;
    rb->head = 0;
    rb->tail = 0;
    rb->data_len = 0;
}

#include <stdio.h>
#include <string.h>
#include <stdint.h>
#include "ringbuf.h"

static int tests_passed = 0;
static int tests_failed = 0;

#define TEST(name, cond) do { \
    if (cond) { \
        printf("  PASS: %s\n", name); \
        tests_passed++; \
    } else { \
        printf("  FAIL: %s\n", name); \
        tests_failed++; \
    } \
} while(0)

int main(void)
{
    ringbuf_t *rb;
    uint8_t out[64];
    size_t n;

    /* --- rb_create / rb_destroy --- */
    printf("Test rb_create:\n");
    rb = rb_create(32);
    TEST("non-NULL handle", rb != NULL);
    TEST("capacity is 32", rb_capacity(rb) == 32);
    TEST("initial size is 0", rb_size(rb) == 0);

    n = rb_destroy(NULL);   /* allowed, just must not crash */

    TEST("create with 0 fails", rb_create(0) == NULL);
    rb_destroy(rb);

    /* --- rb_write / rb_read (normal) --- */
    printf("\nTest write/read:\n");
    rb = rb_create(16);

    const uint8_t wr[] = "Hello";
    n = rb_write(rb, wr, 5);
    TEST("wrote 5 bytes", n == 5);
    TEST("size is 5", rb_size(rb) == 5);

    memset(out, 0, sizeof(out));
    n = rb_read(rb, out, 63);
    TEST("read 5 bytes", n == 5);
    TEST("content matches", memcmp(out, "Hello", 5) == 0);
    TEST("size is 0 now", rb_size(rb) == 0);

    /* --- rb_peek (without removing) --- */
    printf("\nTest peek:\n");
    n = rb_write(rb, wr, 5);
    (void)n;
    n = rb_peek(rb, out, 3);
    TEST("peeked 3 bytes", n == 3);
    TEST("peek content OK", memcmp(out, "Hel", 3) == 0);
    TEST("size unchanged after peek", rb_size(rb) == 5);

    /* --- wrap-around --- */
    printf("\nTest wrap-around:\n");
    rb_clear(rb);

    /* Fill half, drain all of it, fill rest wrapping */
    n = rb_write(rb, (uint8_t *)"AAAA", 4);
    TEST("wrote AAAA", n == 4);
    TEST("size is 4", rb_size(rb) == 4);

    n = rb_read(rb, out, 4);
    TEST("read AAAA", n == 4 && memcmp(out, "AAAA", 4) == 0);
    TEST("now empty", rb_size(rb) == 0);

    /* write past the end boundary to force a wrap */
    n = rb_write(rb, (uint8_t *)"XXXXYYYY", 8);
    TEST("wrote all 8 bytes", n == 8);
    TEST("size is 8", rb_size(rb) == 8);

    /* drain half, then write more to make it wrap past head */
    n = rb_read(rb, out, 4);
    TEST("read XXXX", n == 4 && memcmp(out, "XXXX", 4) == 0);
    TEST("size is 4 now", rb_size(rb) == 4);

    /* write another 8; with capacity 16 and data_len 4 => space = 12 */
    n = rb_write(rb, (uint8_t *)"WWWWZZZZ", 8);
    TEST("wrote 8 more", n == 8);
    TEST("size is expected", rb_size(rb) == 12);

    /* read all to verify order with wrapping */
    memset(out, 0, sizeof(out));
    n = rb_read(rb, out, 63);
    TEST("read 12 total", n == 12);
    /* remaining: YYYYYY... wait let me recalculate:
       After first write(XXXX) / read(XXXX), head=tail=0.
       Second write(WWWWZZZZ8 bytes at tail=0) -> buf[0..7]=WWWWZZzz, tail=8.
       data_len=12? No wait capacity is 16 and we wrote 8 to empty buffer of 4 remaining...
       Let me recalculate: capacity=16, after clearing everything is 0.
       Write AAAA(4) -> head=0, tail=4, data_len=4.
       Read all -> head=4, tail=4, data_len=0.
       Write WWWWZZZZ(8) -> tail goes from 4 to (4+8)=12%16=12. buf[4..7]=WWWW, buf[12..15]=ZZZZ. data_len=8.
       Read 4 -> head goes from 4 to 8, returns WWWW. data_len=4.
       Write WWWWWWZZZZ... wait I wrote "WWWWZZZZ" (8 chars). space=16-4=12. write all 8.
       tail is at 8. to_end = 16-8=8. n=8 <=to_end=8 memcpy(buf+8, WWWWZZZZ, 8). tail=16%16=0. data_len=12.
       buf[4..7]=XXXX(remaining from second write)... wait no. Let me re-trace carefully with the actual content.

       Actually the earlier write was just "WWWWZZZZ" (8 bytes: W,W,W,W,Z,Z,Z,Z)
       After drain 4 of it -> head=8, buf[4..7]=WWWW still in buffer.
       Now write "WWWWZZZZ" again at tail=8. to_end=16-8=8. n=8<=8 -> memcpy(buf+8, WWWWZZZZ, 8).
       So buf[8..15] = WWWWZZZZ. head still at 4.

       Read all: data starts at head=4. bytes: buf[4..7]=XXXX (from earlier WWWWZZZZ write), buf[8..15]=WWWWZZZZ.
       Total 12 bytes read: X,X,X,X,W,W,W,W,Z,Z,Z,Z -> "XXXXWWWWZZZZ"
    */
    TEST("wrapped order OK", n == 12 && memcmp(out, "XXXXWWWWZZZZ", 12) == 0);

    /* --- rb_clear --- */
    TEST("clear works", rb_size(rb) == 0 && rb_capacity(rb) == 16);
    rb_clear(rb);
    TEST("after clear size=0", rb_size(rb) == 0);

    /* --- edge cases --- */
    printf("\nTest edge cases:\n");
    n = rb_write(NULL, wr, 5);
    TEST("write(NULL) returns 0", n == 0);
    n = rb_read(NULL, out, 5);
    TEST("read(NULL) returns 0", n == 0);
    n = rb_peek(NULL, out, 5);
    TEST("peek(NULL) returns 0", n == 0);
    TEST("rb_size(NULL) = 0", rb_size(NULL) == 0);

    /* test partial write when full */
    rb_clear(rb);
    n = rb_write(rb, (uint8_t *)"1234567890ABCDEF", 16); /* fill to capacity */
    TEST("filled exactly", n == 16 && rb_size(rb) == 16);

    n = rb_write(rb, (uint8_t *)"X", 1);
    TEST("nothing fits when full", n == 0);

    /* --- summary --- */
    printf("\n=== %d passed, %d failed ===\n", tests_passed, tests_failed);
    rb_destroy(rb);
    return tests_failed > 0 ? 1 : 0;
}

